#!/usr/bin/env python3
"""Generate docs/TEST-MAP.md: a per-subsystem view of what the test suite tests against.

Scans tests/RO2.Tests/**/*.cs and buckets each file by area (the folder under RO2.Tests)
and by the ORACLE it checks against, inferred from source, not hand-maintained traits:
  - retail-frame : asserts captured retail bytes (Convert.FromHexString) = ground truth
  - needs-data   : [DataFact]/[DataTheory] (loads the real, gitignored data/ tables)
  - logic        : everything else (pure packet/offset/rule tests, inline fixtures)

Run from the repo root: python3 .github/scripts/test-map.py
It is regenerated from source, so it never drifts; re-run it after adding tests.
"""
import glob
import os
import re

ROOT = "tests/RO2.Tests"
ATTR = re.compile(r"\[(DataFact|DataTheory|Fact|Theory)\b")


def area_of(path):
    rel = os.path.relpath(path, ROOT).replace("\\", "/")
    parts = rel.split("/")
    return parts[0] if len(parts) > 1 else "(root)"


def main():
    areas = {}  # area -> dict(files, retail, data, logic, cases)
    for path in glob.glob(os.path.join(ROOT, "**", "*.cs"), recursive=True):
        txt = open(path, encoding="utf-8", errors="ignore").read()
        attrs = ATTR.findall(txt)
        if not attrs:
            continue
        a = areas.setdefault(area_of(path), dict(files=0, retail=0, data=0, logic=0, cases=0))
        a["files"] += 1
        a["cases"] += len(attrs)
        has_hex = "FromHexString" in txt
        has_data = any(x in ("DataFact", "DataTheory") for x in attrs)
        if has_hex:
            a["retail"] += 1
        elif has_data:
            a["data"] += 1
        else:
            a["logic"] += 1

    tot = dict(files=0, retail=0, data=0, logic=0, cases=0)
    for a in areas.values():
        for k in tot:
            tot[k] += a[k]

    lines = [
        "# Test map\n",
        "\n_Generated by `.github/scripts/test-map.py` from the test sources; re-run it after adding tests. Do not hand-edit._\n",
        "\nWhat the suite checks against, per subsystem. A file is counted once by its strongest oracle:\n",
        "\n- **retail-frame**: asserts captured retail packet bytes (`Convert.FromHexString`) = ground truth.\n",
        "- **needs-data**: `[DataFact]`/`[DataTheory]`, loads the real (gitignored) `data/` tables; skipped on CI.\n",
        "- **logic**: pure packet/offset/rule tests and inline fixtures; run everywhere.\n",
        "\n| Area | Files | Test cases | retail-frame | needs-data | logic |\n",
        "|---|---:|---:|---:|---:|---:|\n",
    ]
    for area in sorted(areas):
        a = areas[area]
        lines.append(f"| {area} | {a['files']} | {a['cases']} | {a['retail']} | {a['data']} | {a['logic']} |\n")
    lines.append(f"| **Total** | **{tot['files']}** | **{tot['cases']}** | **{tot['retail']}** | **{tot['data']}** | **{tot['logic']}** |\n")

    os.makedirs("docs", exist_ok=True)
    with open("docs/TEST-MAP.md", "w", encoding="utf-8") as f:
        f.write("".join(lines))
    print("wrote docs/TEST-MAP.md")
    print("".join(lines))


if __name__ == "__main__":
    main()
